import selfies as sf
from rdkit import Chem
parts=['[C][N][Branch1][C][C][C][C][Cl]','[O][=C][Branch1][#Branch2][C][=C][C][=C][C][=C][Ring1][=Branch1][O][C][Branch1][C][F][Branch1][C][F][F]','[C][C][O][C][C]','[C][C][=C][C][=C][C][=C][Ring1][=Branch1]','[Cl]','[O]']
for i,p in enumerate(parts,1):
    try:
        smi=sf.decoder(p)
        mol=Chem.MolFromSmiles(smi)
        print(i,p)
        print('SMILES:',smi)
        print('valid:',mol is not None)
        if mol: print('formula:',Chem.rdMolDescriptors.CalcMolFormula(mol))
    except Exception as e: print(i,'ERROR',repr(e))
